// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import {
  FACET_VALUES_TTL_MS,
  facetPersistence,
  facetNamespace,
  memoryFacetBackend,
} from "../../../main/frontend/graph-explorer/facet-store-persistence.ts";
import { dataRevisionKey, readDataRevision, watchDataRevision } from "../../../main/frontend/graph-explorer/data-revision.ts";

const entry = (value) => ({ checkedAt: 1, predicatesComplete: true, predicates: [["urn:p", [value], true]] });

test("stored values come back within the hour and not after", async () => {
  let now = 1_000_000;
  const backend = memoryFacetBackend();
  const store = facetPersistence({ backend, baseNamespace: "base", revision: "r1", now: () => now });
  await store.write(new Map([["urn:a", entry("one")]]));
  assert.deepEqual([...(await store.read(["urn:a", "urn:b"])).keys()], ["urn:a"]);
  now += FACET_VALUES_TTL_MS + 1;
  assert.equal((await store.read(["urn:a"])).size, 0, "an hour later the value is asked for again");
});

test("a new data revision starts from nothing and clears the older revisions' rows", async () => {
  const backend = memoryFacetBackend();
  const before = facetPersistence({ backend, baseNamespace: "base", revision: "r1" });
  await before.write(new Map([["urn:a", entry("old")]]));
  const other = facetPersistence({ backend, baseNamespace: "other repository", revision: "r1" });
  await other.write(new Map([["urn:a", entry("kept")]]));

  const after = facetPersistence({ backend, baseNamespace: "base", revision: "r2" });
  assert.equal((await after.read(["urn:a"])).size, 0);
  await after.ready;
  assert.equal(backend.size(), 1, "the old revision's row is gone; the other repository's stays");
  assert.equal((await other.read(["urn:a"])).get("urn:a").predicates[0][1][0], "kept");
});

test("clearing drops this repository's rows only", async () => {
  const backend = memoryFacetBackend();
  const mine = facetPersistence({ backend, baseNamespace: "base", revision: "r1" });
  const theirs = facetPersistence({ backend, baseNamespace: "other", revision: "r1" });
  await mine.write(new Map([["urn:a", entry("x")]]));
  await theirs.write(new Map([["urn:a", entry("y")]]));
  await mine.clear();
  assert.equal((await mine.read(["urn:a"])).size, 0);
  assert.equal((await theirs.read(["urn:a"])).size, 1);
});

test("the namespace separates repositories, graph scopes and the inference setting", () => {
  const scope = JSON.stringify(["repository-v2", "/wb", "server", "repo"]);
  assert.notEqual(facetNamespace(scope, "default", true), facetNamespace(scope, "all", true));
  assert.notEqual(facetNamespace(scope, "default", true), facetNamespace(scope, "default", false));
});

test("the data revision key matches the one the Workbench pages write", () => {
  assert.equal(dataRevisionKey("/wb/", "my repo", "server"),
    'rdf4j-workbench-data-revision:["repository-v2","/wb","server","my repo"]');
  const storage = new Map([[dataRevisionKey("/wb", "my repo", "server"), "k1"]]);
  const store = { getItem: (key) => storage.get(key) ?? null };
  assert.equal(readDataRevision(dataRevisionKey("/wb", "my repo", "server"), store), "k1");
  assert.equal(readDataRevision("missing", store), "0");
});

test("another tab's write is heard through storage events for this repository only", () => {
  const listeners = [];
  const target = {
    addEventListener: (type, listener) => listeners.push([type, listener]),
    removeEventListener: (type, listener) => listeners.splice(listeners.findIndex(([, other]) => other === listener), 1),
  };
  const key = dataRevisionKey("/wb", "repo", "server");
  const heard = [];
  const stop = watchDataRevision(key, (revision) => heard.push(revision), target);
  listeners[0][1]({ key, newValue: "k2" });
  listeners[0][1]({ key: dataRevisionKey("/wb", "other", "server"), newValue: "k3" });
  assert.deepEqual(heard, ["k2"]);
  stop();
  assert.equal(listeners.length, 0);
});
